    @GameTest(structure=STRUCTURE,maxTicks=65)public void manualStopSurvivesRealWorldBlockEntityTicksAndActualPowerReleaseStillRestarts(GameTestHelper h){
        setup(h,7,false);h.setBlock(R.west(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.EAST));h.getBlockEntity(R.west(),KineticBlockEntity.class).setGeneratedSpeed(-64);
        var original=new AtomicReference<GantryContraptionEntity>();var target=new AtomicReference<BlockPos>();
        h.runAfterDelay(12,()->{var owner=owner(h);h.assertTrue(owner.getX()>h.absolutePos(P).getX()+.5,"Actual motor moved the native owner before its explicit manual stop");original.set(owner);target.set(owner.getRestorationTransform().apply(BlockPos.ZERO));h.assertTrue(owner.disassemble(),"Actual native manual stop restores the owned mid-rack carriage");});
        h.runAfterDelay(17,()->{h.assertTrue(h.getLevel().getEntitiesOfClass(GantryContraptionEntity.class,new AABB(target.get()).inflate(8)).isEmpty(),"Actual restored BE first/subsequent world ticks cannot invent a new assembly intent");h.assertTrue(original.get().isRemoved()&&!original.get().getContraption().getStorage().ownsContents(),"Retired owner no longer owns the restored stock");h.assertBlockPresent(AllBlocks.GANTRY_CARRIAGE,localWorldPos(h,target.get()));exactCargo(h,localWorldPos(h,target.get().above()));h.assertValueEqual(h.getBlockEntity(R,GantryShaftBlockEntity.class).getSpeed(),-64f,"Real input RPM remains unchanged after manual restoration");h.setBlock(R.north(),Blocks.REDSTONE_BLOCK);});
        h.runAfterDelay(21,()->{h.assertTrue(h.getBlockState(R).getValue(GantryShaftBlock.POWERED),"Real rack redstone mode is powered before release");h.setBlock(R.north(),Blocks.AIR);});
        h.runAfterDelay(28,()->{var resumed=owner(h);h.assertTrue(!resumed.getUUID().equals(original.get().getUUID())&&resumed.getX()>target.get().getX()+.2,"Actual power release grants a fresh accepted owner and movement at the same native RPM");ownedCargo(h,resumed);h.succeed();});
    }

