    @GameTest(structure=STRUCTURE)public void realPortableInterfaceStallHasExactStopPayloadAndRetainsReceiptThroughMissingSourceData(GameTestHelper h)throws Exception{
        var carriage=setup(h,7);h.getBlockEntity(C,BarrelBlockEntity.class).clearContent();h.setBlock(C,AllBlocks.PORTABLE_STORAGE_INTERFACE.defaultBlockState().setValue(PortableStorageInterfaceBlock.FACING,Direction.NORTH));cargo(h,C.east());h.assertTrue(h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(C),h.absolutePos(C.east())))),"Actual native glue joins the real moving interface and named barrel");var endpointPosition=C.north(2).east(2);h.setBlock(endpointPosition,AllBlocks.PORTABLE_STORAGE_INTERFACE.defaultBlockState().setValue(PortableStorageInterfaceBlock.FACING,Direction.SOUTH));var endpoint=h.getBlockEntity(endpointPosition,PortableItemInterfaceBlockEntity.class);
        var phase=new SequencePhase(h.absolutePos(R.west(2)),1,UUID.randomUUID());var sequence=SequenceContext.fromGearshift(SequencerInstructions.TURN_DISTANCE,-64,4);for(int i=0;i<7;i++)h.getBlockEntity(R.east(i),GantryShaftBlockEntity.class).applySequenceContext(sequence,phase);h.assertTrue(carriage.assemble(),"Real sequenced gantry takes its actual PSI actor and component-bearing stock");var owner=owner(h);var id=owner.getUUID();
        for(int i=0;i<40&&!owner.isStalled()&&owner.isAlive();i++){nativeTicks(h,owner,1);endpoint.tick();}
        h.assertTrue(owner.isStalled()&&endpoint.getConnectedEntity()==owner&&owner.getContraption().getActorAt(new BlockPos(0,1,0)).right.stall,"Actual native PSI alignment/timer protocol stalls the original moving owner");var position=owner.position();double remaining=owner.getSequencedOffsetLimit();h.assertTrue(remaining>0&&remaining<4,"Only actual pre-stall travel consumed the distance receipt");var packet=owner.motionPacket();h.assertTrue(packet.owner().equals(id)&&position.equals(packet.stoppedPosition()),"Actual stalled carrier emits its exact XYZ pose and native UUID");
        var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{GantryContraptionUpdatePacket.CODEC.encode(buffer,packet);h.assertValueEqual(GantryContraptionUpdatePacket.CODEC.decode(buffer),packet,"Real registered S2C codec retains the authoritative stop pose");h.assertValueEqual(buffer.readableBytes(),0,"Stopped native payload is consumed exactly");}finally{buffer.release();}
        var support=BlockPos.containing(position.add(.5,.5,.5)).below();missingEntitiesAt(h,support,()->{nativeTicks(h,owner,2);h.assertTrue(owner.position().equals(position)&&owner.getDeltaMovement().lengthSqr()==0&&owner.getLastAssemblyException()!=null&&owner.getLastAssemblyException().canRetry(),"Actual pending supporting native entity data preserves the existing stopped pose");h.assertTrue(owner.motionPacket().stoppedPosition().equals(position)&&owner.getSequencedOffsetLimit()==remaining,"Readiness freeze cannot spend the same producer-generation receipt");});
        h.assertTrue(h.getLevel().getEntity(id)==owner&&owner.hasOwnedStructure()&&owner.getUUID().equals(id),"Missing data never replaces the accepted native owner or its storage phase");h.setBlock(endpointPosition.north(),Blocks.REDSTONE_BLOCK);nativeTicks(h,owner,3);h.assertTrue(!owner.isStalled()&&owner.getX()>position.x&&owner.getSequencedOffsetLimit()<remaining&&owner.motionPacket().stoppedPosition()==null,"Actual endpoint redstone disconnect resumes the same owner and original remaining distance");var stock=owner.getContraption().getStorage().getAllItemStorages().get(new BlockPos(1,1,0)).getStackInSlot(0);h.assertTrue(stock.is(Items.DIAMOND)&&stock.getCount()==7&&stock.has(DataComponents.CUSTOM_NAME),"Exact named cargo remains with the same real native carrier");h.succeed();
    }
    @GameTest(structure=STRUCTURE)public void nativeCurrentStringAxisDecodesAllSixDirectionsWithoutReportingWrongType(GameTestHelper h)throws Exception{nativeAxisFormat(h,false);h.succeed();}
    @GameTest(structure=STRUCTURE)public void nativeLegacyIntegerAxisDecodesAllSixDirectionsWithoutReportingWrongType(GameTestHelper h)throws Exception{nativeAxisFormat(h,true);h.succeed();}
    private static void nativeAxisFormat(GameTestHelper h,boolean legacy)throws Exception{
        for(var direction:Direction.values()){
            var face=direction.getAxis()==Direction.Axis.Y?Direction.EAST:Direction.UP;var start=R.relative(face);var front=start.relative(face);
            for(int i=0;i<3;i++)h.setBlock(R.relative(direction,i),AllBlocks.GANTRY_SHAFT.defaultBlockState().setValue(GantryShaftBlock.FACING,direction));
            var state=AllBlocks.GANTRY_CARRIAGE.defaultBlockState().setValue(GantryCarriageBlock.FACING,face);if(GantryCarriageBlock.getValidGantryShaftAxis(state)!=direction.getAxis())state=state.cycle(GantryCarriageBlock.AXIS_ALONG_FIRST_COORDINATE);
            h.setBlock(start,state);cargo(h,front);for(int i=0;i<3;i++)rpm(h.getBlockEntity(R.relative(direction,i),GantryShaftBlockEntity.class),-64);
            h.assertTrue(h.getBlockEntity(start,GantryCarriageBlockEntity.class).assemble(),"Real source rack/carriage/cargo assembles axis "+direction);var original=owner(h);nativeTicks(h,original,6);var id=original.getUUID();var position=original.position();
            var saveProblems=new net.minecraft.util.ProblemReporter.Collector();var output=TagValueOutput.createWithContext(saveProblems,h.getLevel().registryAccess());h.assertTrue(original.saveAsPassenger(output)&&saveProblems.isEmpty(),"Genuine native owner save has no problems: "+saveProblems.getTreeReport());var tag=output.buildResult();
            h.assertValueEqual(tag.getStringOr("GantryAxis",""),direction.name(),"Actual native current writer preserves its source STRING axis before legacy migration");if(legacy)tag.putInt("GantryAxis",direction.get3DDataValue());
            original.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);h.assertTrue(h.getLevel().getEntity(id)==null,"Original native representation really unloaded before its exact UUID is loaded");
            var problems=new net.minecraft.util.ProblemReporter.Collector();var input=net.minecraft.world.level.storage.TagValueInput.create(problems,h.getLevel().registryAccess(),tag);
            var loaded=EntityType.loadEntityRecursive(input,h.getLevel(),new EntitySpawnRequest(EntitySpawnReason.LOAD,false),EntityProcessor.NOP);
            h.assertTrue(loaded instanceof GantryContraptionEntity&&loaded.getType()==AllEntityTypes.GANTRY_CONTRAPTION&&loaded.getUUID().equals(id),"Genuine registered native factory restores exact class/type/original UUID for "+(legacy?"INT ":"STRING ")+direction);
            h.assertTrue(problems.isEmpty(),"Both supported genuine axis encodings must produce zero native ValueInput diagnostics: "+problems.getTreeReport());var owner=(GantryContraptionEntity)loaded;
            h.assertTrue(owner.getMovementAxis()==direction&&owner.position().distanceToSqr(position)<1e-12&&owner.hasOwnedStructure(),"Exact source axis/double pose/REMOVED storage ownership survive native read");
            h.assertTrue(owner.getContraption().getBlocks().keySet().equals(Set.of(BlockPos.ZERO,BlockPos.ZERO.relative(face))),"Actual source-oriented carriage and exact front cargo cells survive native read");
            var stock=owner.getContraption().getStorage().getAllItemStorages().get(BlockPos.ZERO.relative(face)).getStackInSlot(0);h.assertTrue(stock.is(Items.DIAMOND)&&stock.getCount()==7&&Component.literal("Gantry cargo").equals(stock.get(DataComponents.CUSTOM_NAME)),"Exactly seven original component-bearing diamonds remain in the single loaded owner");
            h.assertTrue(h.getLevel().addFreshEntity(owner)&&h.getLevel().getEntity(id)==owner,"Real native UUID admission accepts this one original owner");nativeTicks(h,owner,25);
            h.assertTrue(owner.isRemoved()&&!owner.getContraption().getStorage().ownsContents()&&h.getLevel().getEntity(id)==null,"Loaded source owner completes genuine rack travel/restoration and retires its original UUID");
            var target=start.relative(direction,2);h.assertBlockPresent(AllBlocks.GANTRY_CARRIAGE,target);var restored=h.getBlockEntity(target.relative(face),BarrelBlockEntity.class).getItem(0);h.assertTrue(restored.is(Items.DIAMOND)&&restored.getCount()==7&&Component.literal("Gantry cargo").equals(restored.get(DataComponents.CUSTOM_NAME)),"Exact original world cargo returns after source axis-specific native movement");
            h.getBlockEntity(target.relative(face),BarrelBlockEntity.class).clearContent();h.setBlock(target.relative(face),Blocks.AIR);h.setBlock(target,Blocks.AIR);for(int i=0;i<3;i++)h.setBlock(R.relative(direction,i),Blocks.AIR);
        }
    }

